import sys

def main():
    input = sys.stdin.readline
    line = input()
    if not line:
        return
    n = int(line.strip())
    bal = 0
    for _ in range(n):
        line = input()
        for ch in line:
            if ch == '{':
                bal += 1
            elif ch == '}':
                bal -= 1
                if bal < 0:
                    print("N")
                    return
    if bal == 0:
        print("S")
    else:
        print("N")

